require_once __DIR__.'/../src/includes/cms.php';require_once __DIR__.'/../src/includes/studio-access.php';require_once __DIR__.'/../src/includes/studio-finance.php';require_once __DIR__.'/../src/includes/studio-finance-view.php';
$db=cms_db();st_install_access($db);st_install_finance($db);$checks=0;
function check(bool $condition,string $message): void {global $checks;if(!$condition)throw new RuntimeException('FAIL '.$message);$checks++;}
function blocked(callable $operation,string $message,string $contains=''): void {try{$operation();}catch(Throwable $e){check($contains===''||str_contains($e->getMessage(),$contains),$message.' / '.$e->getMessage());return;}throw new RuntimeException('FAIL expected block: '.$message);}
function fresh(array $u): array {return st_refresh_user($u);}
function staff(string $name,string $scope,array $permissions,array $events=[]): array {global $db;$db->prepare("INSERT INTO users(username,password_hash,role,email,active,display_name,permissions,modules,event_scope,must_change_password) VALUES(?,?,'COORDINATOR',?,1,?,?,?, ?,0)")->execute([$name,password_hash('Test-passphrase-2026!',PASSWORD_DEFAULT),$name.'@example.invalid',$name,json_encode($permissions),'[]',$scope]);$id=(int)$db->lastInsertId();foreach($events as $event)$db->prepare('INSERT INTO st_event_assignments(user_id,event_id,assigned_by,assigned_at) VALUES(?,?,1,?)')->execute([$id,$event,gmdate('c')]);$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);return $s->fetch();}
function command(array $u,string $action,array $data): int {return st_finance_mutate($u,$action,['environment'=>'live','request_key'=>bin2hex(random_bytes(24)),...$data]);}
function expense(int $id): array {global $db;return st_finance_query($db,'SELECT * FROM st_expenses WHERE id=?',[$id])[0];}
function make_expense(array $u,int $event,string $amount='600.00',string $title='Stage equipment'): int {return command($u,'expense_save',['event_id'=>$event,'title'=>$title,'category'=>'equipment','payee'=>'Local supplier','amount'=>$amount,'description'=>'Sound and stage requirements','invoice_reference'=>'INV-'.bin2hex(random_bytes(6))]);}
function submit(array $u,int $id): void {command($u,'expense_submit',['id'=>$id,'revision'=>expense($id)['revision']]);}
function approve(array $u,int $id): void {command($u,'expense_approve',['id'=>$id,'revision'=>expense($id)['revision'],'note'=>'Invoice and allocation verified']);}
function gateway_order(int $event,string $state,int $amount,string $environment,int $participant,string $payment): int {global $db;$now=gmdate('c');$db->prepare('INSERT INTO az_orders(public_id,participant_id,event_id,event_slug,ticket_type,snapshot,answers,quantity,unit_price,amount,state,environment,gateway_order,gateway_payment,expires_at,created_at,updated_at,provider) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(['ORDER-'.strtoupper(bin2hex(random_bytes(8))),$participant,$event,'test-event','entry','{}','{}',2,$amount/2,$amount,$state,$environment,'GW-'.bin2hex(random_bytes(8)),$payment,time()+600,$now,$now,'phonepe']);return (int)$db->lastInsertId();}
try{
    $db->exec("UPDATE users SET must_change_password=0 WHERE role='SUPERADMIN'");$master=$db->query("SELECT * FROM users WHERE role='SUPERADMIN'")->fetch();$events=$db->query("SELECT id FROM cms_content WHERE type='event' ORDER BY id LIMIT 2")->fetchAll(PDO::FETCH_COLUMN);[$event1,$event2]=array_map('intval',$events);
    $all=['finance.view','finance.allocate','finance.submit','finance.approve','finance.record','finance.export','finance.close'];
    $coordinator=staff('maker','assigned',$all,[$event1]);$reviewer=staff('reviewer','assigned',['finance.view','finance.approve'],[$event1]);$finance=staff('finance','all',$all);$other=staff('other-event','assigned',['finance.view','finance.submit'],[$event2]);$readOnly=staff('readonly','assigned',['finance.view'],[$event1]);$denied=staff('no-finance','assigned',[],[$event1]);
