    blocked(fn()=>st_finance_summary($denied,$event1),'Finance view permission required');blocked(fn()=>st_finance_summary($coordinator,$event2),'Other event report blocked');blocked(fn()=>command($coordinator,'allocate',['event_id'=>$event1,'amount'=>'1000.00','revision'=>'0','note'=>'Scope bypass']),'Scoped coordinator cannot allocate even with module permission');
    command($finance,'allocate',['event_id'=>$event1,'amount'=>'1000.00','revision'=>'0','note'=>'Approved festival budget']);command($finance,'allocate',['event_id'=>$event2,'amount'=>'2000.00','revision'=>'0','note'=>'Approved festival budget']);
