    submit($coordinator,$first);blocked(fn()=>approve($coordinator,$first),'Maker cannot self approve','independent');approve($reviewer,$first);
    check(st_finance_summary($coordinator,$event1)['approved_commitments']===60000,'Approved amount immediately reserved');check(st_finance_summary($coordinator,$event1)['available_budget']===40000,'Remaining allocation subtracts commitment');
    $second=make_expense($coordinator,$event1,'500.00','Prize stock');submit($coordinator,$second);blocked(fn()=>approve($reviewer,$second),'Cannot overcommit allocation','exceed');check(expense($second)['status']==='SUBMITTED','Failed approval rolled back');
    blocked(fn()=>command($finance,'allocate',['event_id'=>$event1,'revision'=>1,'amount'=>'500.00','note'=>'Invalid reduction']),'Allocation cannot drop below commitments');blocked(fn()=>command($finance,'allocate',['event_id'=>$event1,'revision'=>0,'amount'=>'1200.00','note'=>'Stale']),'Budget optimistic revision protects concurrent edits');
    blocked(fn()=>command($coordinator,'expense_pay',['id'=>$first,'revision'=>expense($first)['revision'],'payment_reference'=>'BAD']),'Coordinator cannot record central bank payment');
    $payment=['environment'=>'live','request_key'=>bin2hex(random_bytes(24)),'id'=>$first,'revision'=>expense($first)['revision'],'payment_reference'=>'BANK-PAID-1'];$id=st_finance_mutate($finance,'expense_pay',$payment);check($id===$first,'Payment records original expense');check(st_finance_mutate($finance,'expense_pay',$payment)===$first,'Payment retries are idempotent');
    check(st_finance_sum($db,"SELECT COUNT(*) FROM st_finance_ledger WHERE kind='EXPENSE_PAYMENT'")===1,'One journal posting for duplicate payment');blocked(fn()=>st_finance_mutate($finance,'expense_pay',[...$payment,'payment_reference'=>'CHANGED']),'Idempotency key cannot be reused with different input');
    check(st_finance_summary($coordinator,$event1)['paid_expenses']===60000,'Payment moves reservation to spending');check(st_finance_summary($coordinator,$event1)['approved_commitments']===0,'Payment releases only its reservation');check(st_finance_summary($coordinator,$event1)['available_budget']===40000,'No double count of paid reservation');
    blocked(fn()=>command($coordinator,'expense_save',['id'=>$first,'revision'=>expense($first)['revision'],'event_id'=>$event1,'title'=>'Rewrite payment','category'=>'other','payee'=>'X','amount'=>'1','description'=>'Bad','invoice_reference'=>'BAD']),'Paid expense cannot be edited');blocked(fn()=>command($finance,'expense_void',['id'=>$first,'revision'=>expense($first)['revision'],'note'=>'Bad deletion']),'Paid expense cannot be voided');
    command($finance,'expense_reverse',['id'=>$first,'revision'=>expense($first)['revision'],'payment_reference'=>'BANK-RETURN-1','note'=>'Full equipment deposit returned']);check(expense($first)['status']==='REVERSED','Original expense retains reversal state');check(st_finance_summary($coordinator,$event1)['paid_expenses']===0,'Actual return restores spending');
    check(st_finance_sum($db,"SELECT COUNT(*) FROM st_finance_ledger WHERE kind IN ('EXPENSE_PAYMENT','EXPENSE_REVERSAL')")===2,'Original and reversal retained');blocked(fn()=>command($finance,'expense_reverse',['id'=>$first,'revision'=>expense($first)['revision'],'payment_reference'=>'REPEAT','note'=>'Repeat']),'No double reversal');
    approve($reviewer,$second);command($reviewer,'expense_void',['id'=>$second,'revision'=>expense($second)['revision'],'note'=>'Prize purchase cancelled']);check(st_finance_summary($coordinator,$event1)['available_budget']===100000,'Reviewer can release approved reserve without submission permission');
    $ownFinance=make_expense($finance,$event1,'10.00','Finance maker');submit($finance,$ownFinance);blocked(fn()=>approve($finance,$ownFinance),'Global operator cannot approve own expense');approve($reviewer,$ownFinance);blocked(fn()=>command($finance,'expense_pay',['id'=>$ownFinance,'revision'=>expense($ownFinance)['revision'],'payment_reference'=>'SELF']),'Finance maker cannot certify own payout');command($master,'expense_pay',['id'=>$ownFinance,'revision'=>expense($ownFinance)['revision'],'payment_reference'=>'BANK-OWN-2']);
    $income=command($finance,'income_post',['event_id'=>$event1,'amount'=>'2500.00','title'=>'Sponsor contribution','source'=>'sponsorship','reference'=>'SPONSOR-1','note'=>'Signed receipt received']);check(st_finance_summary($coordinator,$event1)['manual_income']===250000,'Manual sponsorship counted');blocked(fn()=>command($finance,'income_post',['event_id'=>$event2,'amount'=>'2500.00','title'=>'Duplicate','source'=>'grant','reference'=>'SPONSOR-1','note'=>'duplicate']),'Duplicate bank reference rejected across events');
    command($finance,'income_reverse',['id'=>$income,'reference'=>'SPONSOR-RETURN','note'=>'Donation entry corrected']);check(st_finance_summary($coordinator,$event1)['manual_income']===0,'Manual income reversal retained and netted');
    $paid=gateway_order($event1,'PAID',10000,'live',101,'TXN1');$refunded=gateway_order($event1,'REFUNDED',20000,'live',102,'TXN2');$review=gateway_order($event1,'PAID_REVIEW',4000,'live',101,'TXN3');gateway_order($event1,'PENDING',3000,'live',103,'');gateway_order($event1,'PAID',90000,'test',101,'TESTTXN');gateway_order($event2,'PAID',80000,'live',201,'EVENT2TXN');
    $db->prepare('INSERT INTO az_refunds(refund_id,order_id,amount,received_at) VALUES(?,?,?,?)')->execute(['REFUND1',$refunded,20000,gmdate('c')]);
    $totals=st_finance_summary($coordinator,$event1);check($totals['gross']===34000,'Captured PAID, REFUNDED and PAID_REVIEW included');check($totals['refunds']===20000,'Only actual verified refund rows subtracted');check($totals['net_registration']===14000,'Refund net correct');check($totals['paying_participants']===2,'Paying people deduplicated across orders');check($totals['pending_orders']===1,'Pending order separate');check(st_finance_summary($coordinator,null)['gross']===34000,'All-access report still respects event assignments');check(st_finance_summary($coordinator,$event1,'test')['gross']===90000,'Live/test gross separate');
    blocked(fn()=>command($finance,'settlement_record',['provider'=>'phonepe','reference'=>'BATCH-BAD','bank_reference'=>'BANK-BAD','bank_date'=>'2026-10-03','order_ids'=>(string)$paid,'fees'=>'1.00','net'=>'100.00']),'Settlement must match net arithmetic');
    command($finance,'settlement_record',['provider'=>'phonepe','reference'=>'BATCH-1','bank_reference'=>'BANK-DEPOSIT-1','bank_date'=>'2026-10-03','order_ids'=>$paid.','.$review,'fees'=>'1.00','net'=>'139.00']);check(st_finance_summary($coordinator,$event1)['settled_gross']===14000,'Verified bank batch tracked separately');check(st_finance_summary($coordinator,$event1)['unsettled_gross']===20000,'Remaining captures have no bank batch');
    blocked(fn()=>command($finance,'settlement_record',['provider'=>'phonepe','reference'=>'BATCH-DUP','bank_reference'=>'BANK-DUP','bank_date'=>'2026-10-03','order_ids'=>(string)$paid,'fees'=>'0','net'=>'100.00']),'Orders cannot be double settled');blocked(fn()=>st_finance_rows($coordinator,'settlements'),'Bank-wide batch private to global finance scope');
