    $shared1=gateway_order($event1,'PAID',10100,'live',104,'SHARED1');$shared2=gateway_order($event2,'PAID',20200,'live',202,'SHARED2');
    command($finance,'settlement_record',['provider'=>'phonepe','reference'=>'SHARED-BATCH','bank_reference'=>'SHARED-BANK','bank_date'=>'2026-10-03','order_ids'=>$shared1.','.$shared2,'fees'=>'1.01','net'=>'301.99']);
    check(st_finance_sum($db,'SELECT fees FROM st_settlement_orders WHERE order_id=?',[$shared1])===34,'Shared batch fee rounded deterministically for event one');check(st_finance_sum($db,'SELECT fees FROM st_settlement_orders WHERE order_id=?',[$shared2])===67,'Shared batch fee allocated for event two');check(st_finance_sum($db,'SELECT SUM(fees) FROM st_settlement_orders WHERE order_id IN (?,?)',[$shared1,$shared2])===101,'All shared batch paise allocated exactly');
