    $draft=make_expense($coordinator,$event1,'2.00','Unfinished');blocked(fn()=>command($finance,'close',['event_id'=>$event1,'note'=>'Premature close']),'Open drafts block closeout');command($coordinator,'expense_void',['id'=>$draft,'revision'=>expense($draft)['revision'],'note'=>'No longer needed']);
    $close=command($finance,'close',['event_id'=>$event1,'note'=>'Treasurer approved closeout']);$closeout=st_finance_query($db,'SELECT * FROM st_closeouts WHERE id=?',[$close])[0];check(!st_finance_closeout_changed($coordinator,$closeout),'New snapshot matches');blocked(fn()=>make_expense($coordinator,$event1),'Closeout freezes expense drafts');blocked(fn()=>command($finance,'income_post',['event_id'=>$event1,'amount'=>'5.00','title'=>'Late posting','source'=>'other','reference'=>'LATE','note'=>'closed']),'Closeout freezes manual receipts');
