    command($finance,'reopen',['event_id'=>$event1,'note'=>'Investigate late gateway refund']);check(st_finance_budget($db,$event1,'live')['closed']===0,'Controlled reopen');check(st_finance_sum($db,'SELECT COUNT(*) FROM st_closeouts WHERE event_id=?',[$event1])===1,'Reopen preserves old snapshot');
