    $_GET=['section'=>'finance','environment'=>'live'];ob_start();st_finance_view($reviewer,'finance',$event1);$queueView=ob_get_clean();check(str_contains($queueView,'expense='.$historicPending.'#expense-'.$historicPending),'Old queue item links to a directly actionable expense');$_GET=[];
    $db->prepare('UPDATE users SET session_version=session_version+1 WHERE id=?')->execute([$coordinator['id']]);blocked(fn()=>make_expense($coordinator,$event1),'Revoked session denied inside transaction');check(st_finance_summary($coordinator,null)['gross']===0,'Stale user cannot see old event totals');
    check(st_finance_sum($db,'SELECT COUNT(*) FROM st_finance_audit')>20,'Mutation audit retained');check(st_finance_sum($db,'SELECT COUNT(*) FROM cms_audit WHERE action LIKE ?', ['finance.%'])>20,'Central audit receives financial actions');
